def transform(grid):
 h=len(grid);w=len(grid[0]);out=[[0]*w for _ in range(h)]
 colors=sorted({v for row in grid for v in row if v},reverse=True)
 data=[]
 for v in colors:
  pts=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==v]
  pr,pc=min(pts,key=lambda p:(2*p[0]-h+1)**2+(2*p[1]-w+1)**2)
  data.append((v,pts,pc))
  for r,c in pts:
   for x in range(min(c,pc),max(c,pc)+1):out[r][x]=v
 for v,pts,pc in data:
  for r in range(min(r for r,c in pts),max(r for r,c in pts)+1):out[r][pc]=v
 return out

